parameters.jsonSchemaExample:
{
  "type": "object",
  "properties": {
    "message": {
      "type": "string",
      "description": "The natural language response that will be sent to the customer"
    },
    "is_order": {
      "type": "boolean",
      "description": "True if the customer is placing or confirming an order"
    },
    "items": {
      "type": "array",
      "description": "List of food items selected by the customer",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name of the selected menu item"
          },
          "quantity": {
            "type": "integer",
            "description": "Quantity of the selected item"
          },
          "unit_price": {
            "type": "number",
            "description": "Price of one unit of the selected item in EGP"
          },
          "total_price": {
            "type": "number",
            "description": "Total price for this item based on quantity"
          }
        },
        "required": [
          "name",
          "quantity",
          "unit_price",
          "total_price"
        ]
      }
    },
    "additions": {
      "type": "array",
      "description": "List of additions selected by the customer",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name of the selected addition"
          },
          "quantity": {
            "type": "integer",
            "description": "Quantity of the addition"
          },
          "unit_price": {
            "type": "number",
            "description": "Price of one addition in EGP"
          },
          "total_price": {
            "type": "number",
            "description": "Total price for this addition"
          }
        },
        "required": [
          "name",
          "quantity",
          "unit_price",
          "total_price"
        ]
      }
    },
    "total": {
      "type": "number",
      "description": "Total order price in EGP"
    }
  },
  "required": [
    "message",
    "is_order",
    "items",
    "additions",
    "total"
  ]
}
